// real, src/sharing.ts (trimmed)
export function sealForRecipient(recipientPublicKeyPem: string, plaintext: Buffer): ShareToken {
  const oneTimeKey = randomBytes(32); // AES-256, fresh every call
  const blob = encrypt(oneTimeKey, plaintext); // symmetric: the actual data
  const wrappedKey = publicEncrypt({ key: recipientPublicKeyPem, ...RSA_OPTIONS }, oneTimeKey); // asymmetric: only the key
  return { wrappedKey: wrappedKey.toString("base64"), blob };
}

