// real, src/manager.ts commit (trimmed)
private async commit(record: VaultRecord, fields: { salt: Buffer; canary: EncryptedBlob; entries: StoredEntry[]; sharingPublicKey: string | null; wrappedPrivateKey: EncryptedBlob | null; }): Promise<void> {
  const snapshot: PersistedVault = {
    ownerId: record.ownerId,
    createdAt: record.createdAt,
    salt: fields.salt.toString("base64"), // explicit, not record.salt
    canary: fields.canary,                // explicit, not record.canary
    entries: fields.entries.map((e) => ({ id: e.id, blob: e.blob, createdAt: e.createdAt, updatedAt: e.updatedAt, lastUsedAt: e.lastUsedAt })),
    sharingPublicKey: fields.sharingPublicKey,
    wrappedPrivateKey: fields.wrappedPrivateKey,
  };
  await withTimeout((signal) => this.store.persist(snapshot, signal), this.commitTimeoutMs);
}
